with parsed as (select id, coupon_codes, items, attributes, coalesce(attributes['gift'], 'none') as gift_or_default, coalesce(attributes['utm_source'], 'unknown') as utm_source_or_default, transform(filter(items, item -> item.promo is not null), item -> struct(item.product_id as pid, round(item.price * 0.9, 2) as discounted_price)) as promo_lines, array_max(transform(items, item -> item.price)) as max_item_price from carts) select case when max_item_price >= 236 then 'PREMIUM' else 'STANDARD' end as max_item_price_tier, count(distinct utm_source_or_default) as distinct_utm_source_or_defaults, count(distinct id) as distinct_ids, count(*) as event_count, percentile_approx(max_item_price, array(0.25, 0.5, 0.75)) as max_item_price_quartiles, approx_percentile(max_item_price, 0.5) as max_item_price_p50, grouping(case when max_item_price >= 236 then 'PREMIUM' else 'STANDARD' end) as grouping_id from parsed group by cube (case when max_item_price >= 236 then 'PREMIUM' else 'STANDARD' end) order by distinct_ids nulls first;
